package com.mendes.scheduling_platform.user;
import com.mendes.scheduling_platform.exception.BusinessException; import com.mendes.scheduling_platform.plan.PlanService; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.crypto.password.PasswordEncoder; import java.util.List; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class UserServiceTest { @Mock UserRepository users; @Mock PasswordEncoder encoder; @Mock PlanService plans; @InjectMocks UserService service;
 @Test void managerCannotCreateOwner(){assertThrows(BusinessException.class,()->service.create(1L,"Novo","novo@test.com","password",User.Role.OWNER,auth("ROLE_MANAGER")));verify(users,never()).save(any());}
 @Test void managerCanCreateEmployee(){when(encoder.encode("password")).thenReturn("hash");when(users.save(any())).thenAnswer(i->i.getArgument(0));User user=service.create(1L,"Novo","novo@test.com","password",User.Role.EMPLOYEE,auth("ROLE_MANAGER"));assertEquals(User.Role.EMPLOYEE,user.getRole());assertEquals(1L,user.getTenantId());verify(plans).assertCanCreateUser(1L);}
 @Test void employeeCannotCreateUsers(){assertThrows(BusinessException.class,()->service.create(1L,"Novo","novo@test.com","password",User.Role.EMPLOYEE,auth("ROLE_EMPLOYEE")));}
 private UsernamePasswordAuthenticationToken auth(String role){return new UsernamePasswordAuthenticationToken("actor",null,List.of(new SimpleGrantedAuthority(role)));}}
